mapper.select:
		SELECT  NVL(deal.SHARE_AMT,deal.PRIN_AMT) prinAmt,
		INFO.MDATE,
		(DEAL.TRADE_DATE+#{fixterm,jdbcType=INTEGER}) prinAmtMdate
        FROM TRD_PRODUCT_DEAL DEAL
        LEFT JOIN FIN_PRODUCT INFO ON DEAL.FINPROD_ID=INFO.FINPROD_ID
		WHERE DEAL.TRADE_STATUS !='03' AND DEAL.IS_CANCEL ='N'
		AND DEAL.FINPROD_ID=#{prodid,jdbcType=VARCHAR}
		AND DEAL.TRADE_DATE<=#{caldate,jdbcType=DATE}
		AND (DEAL.TRADE_DATE+#{fixterm,jdbcType=INTEGER})>#{caldate,jdbcType=DATE}

		AND DEAL.PS in ('C1','C2')

	select 
    case when max(info.mdate)-(max(deal.vdate)+#{fixterm,jdbcType=INTEGER})>0
		then max(deal.vdate)+#{fixterm,jdbcType=INTEGER}
		else  max(info.mdate)  end   prinAmtMdate
    from TRD_PRODUCT_DEAL deal
    left join FIN_PRODUCT info on deal.FINPROD_ID=info.FINPROD_ID
	where deal.TRADE_STATUS !='03' AND deal.IS_CANCEL ='N'
	and deal.FINPROD_ID=#{prodid,jdbcType=VARCHAR}
	and deal.vdate<=#{caldate,jdbcType=DATE}
	and (deal.vdate+#{fixterm,jdbcType=INTEGER})>#{caldate,jdbcType=DATE}

select deal.mdate prinAmtMdate,
NVL(deal.PRIN_AMT,deal.TRADE_AMT) prinAmt
from TRD_PRODUCT_DEAL deal
left join FIN_PRODUCT info on info.FINPROD_ID=deal.FINPROD_ID
where deal.TRADE_STATUS !='03' AND deal.IS_CANCEL ='N'
and info.FINPROD_ID=#{prodid,jdbcType=VARCHAR}
 and deal.vdate<=#{caldate,jdbcType=DATE} 
and deal.mdate>#{caldate,jdbcType=DATE}

 select max(deal.mdate) prinAmtMdate
from TRD_PRODUCT_DEAL deal
left join FIN_PRODUCT info on info.FINPROD_ID=deal.FINPROD_ID
where deal.TRADE_STATUS !='03' AND deal.IS_CANCEL ='N'
and  info.FINPROD_ID=#{prodid,jdbcType=VARCHAR}
and deal.vdate<= #{caldate,jdbcType=DATE}
and deal.mdate>#{caldate,jdbcType=DATE}
